import itertools

def check_condition(n, d, coeffs):
    # R(x) = x^d + coeffs[d-1]*x^{d-1} + ... + coeffs[0]
    def R(x):
        res = x**d
        for i, c in enumerate(coeffs):
            res += c * (x**(d-1-i))
        return res

    # Try k from 1 to n
    for k in range(1, n + 1):
        # Try to find k+1 distinct integers a_1, ..., a_{k+1}
        # We'll search in a small range first
        M = 10
        for args in itertools.product(range(-M, M + 1), repeat=k+1):
            if len(set(args)) == k+1:
                a = list(args)
                if R(a[k]) == sum(R(a[i]) for i in range(k)):
                    return True
    return False

def solve_for_n(n):
    # We need to check for all d <= n and all Q with deg Q < d
    # This is equivalent to checking for all monic R of degree d
    # But there are infinitely many R. We can check a few.
    # For a given d, we want to know if there's any R that fails.
    # If we find one R that fails for all k <= n, then n is not a solution.

    for d in range(1, n + 1):
        # Check some polynomials R(x) = x^d + ax^{d-1} + ...
        # Since we want to find if any R fails, we can try some small coefficients.
        for a in range(-2, 3):
            for b in range(-2, 3):
                # For d=1, R(x) = x + a
                # For d=2, R(x) = x^2 + ax + b
                # For d=3, R(x) = x^3 + ax^2 + bx + c
                # Let's just test some coefficients.
                if d == 1:
                    coeffs = [a]
                    if not check_condition(n, d, coeffs):
                        return False, d, coeffs
                elif d == 2:
                    coeffs = [a, b]
                    if not check_condition(n, d, coeffs):
                        return False, d, coeffs
                elif d == 3:
                    # Let's try a few c's
                    for c in range(-2, 3):
                        coeffs = [a, b, c]
                        if not check_condition(n, d, coeffs):
                            return False, d, coeffs
    return True, None, None

