def check_all_k_fail_proper_v4(d, n, coeffs):
    M = 60
    vals = [R_fixed(x, d, coeffs) for x in range(-M, M + 1)]
    indices = list(range(-M, M + 1))

    # Pre-calculate sets of sums
    # sum_vals[k] will be the set of all sums of k distinct elements from vals
    # But we need to know which elements are in each sum to ensure distinctness.
    # This is getting complicated. Let's use a simpler approach.

    # For a fixed k, we want to know if there's a sum of k distinct elements
    # from vals \ {vals[i_last]} that equals vals[i_last].
    # This is equivalent to: is there a set of k+1 distinct elements {v_1, ..., v_{k+1}}
    # from vals such that 2 * v_last = sum(v_i for i=1..k+1)?

    # Let's use a simpler search for each k.
    for k in range(1, n + 1):
        found_k = False
        # We need to find k+1 distinct indices i_1, ..., i_{k+1}
        # such that vals[i_{k+1}] = sum(vals[i_j] for j=1..k)
        # which is 2 * vals[i_{k+1}] = sum(vals[i_j] for j=1..k+1)

        # For a fixed k, let's use a simple recursive search with a limit.
        def search(count, current_target, last_idx, excluded_idx):
            if count == 0:
                return current_target == 0
            if last_idx < 0:
                return False

            # Try including indices[last_idx]
            if last_idx != excluded_idx:
                if search(count - 1, current_target - vals[last_idx], last_idx - 1, excluded_idx):
                    return True

            # Try excluding indices[last_idx]
            if search(count, current_target, last_idx - 1, excluded_idx):
                return True

            return False

        for i_last in range(len(indices)):
            if search(k, vals[i_last], len(indices) - 1, i_last):
                found_k = True
                break

        if found_k:
            return False
    return True

