import itertools

def check_n(n):
    for d in range(1, n + 1):
        # We need to check if for every R(x) = x^d + c_{d-1}x^{d-1} + ... + c_0
        # there exists k <= n and k+1 distinct a_i.
        # Since we can't check all c_i, let's check some small ones.
        # For a fixed d, we can try some c_i.
        for c in list(itertools.product(range(-5, 6), repeat=d)):
            coeffs = [1] + list(c)
            # coeffs = [c_d, c_{d-1}, ..., c_0]

            def R(x):
                res = 0
                for i, coeff in enumerate(coeffs):
                    res += coeff * (x**(d-i))
                return res

            found_k = False
            for k in range(1, n + 1):
                # Search for k+1 distinct integers a_1, ..., a_{k+1}
                # Search range for a_i
                for a in itertools.product(range(-10, 11), repeat=k+1):
                    if len(set(a)) == k+1:
                        sum_R = sum(R(ai) for ai in a[:k])
                        if R(a[k]) == sum_R:
                            found_k = True
                            break
                    else:
                        continue
                if found_k:
                    break

            if not found_k:
                return False, (d, c)
    return True, None

