import itertools

def check_n_fast(n):
    for d in range(1, n + 1):
        # For each d, we check a smaller set of coefficients.
        # c_0 can be anything, but it doesn't affect R(a_1) = R(a_2) etc.
        # R(a_{k+1}) - \sum R(a_i) = 0
        # Let R(x) = x^d + c_{d-1}x^{d-1} + ... + c_1x + c_0.
        # The c_0's cancel out:
        # (a_{k+1}^d + ... + c_1 a_{k+1}) - \sum (a_i^d + ... + c_1 a_i) = 0
        # The c_0 cancels. So we only need to check c_1, ..., c_{d-1}.
        for c in list(itertools.product(range(-2, 3), repeat=d-1)):
            coeffs = [1] + list(c)
            # coeffs = [c_d, c_{d-1}, ..., c_1] (no c_0)

            def R(x):
                res = 0
                for i, coeff in enumerate(coeffs):
                    res += coeff * (x**(d-i))
                return res

            found_k = False
            for k in range(1, n + 1):
                # Try a smaller range for a_i
                for a in itertools.product(range(-5, 6), repeat=k+1):
                    if len(set(a)) == k+1:
                        if R(a[k]) == sum(R(ai) for ai in a[:k]):
                            found_k = True
                            break
                    else:
                        continue
                if found_k:
                    break

            if not found_k:
                return False, (d, c)
    return True, None

