            # Since R is strictly increasing, there is at most one a3.
            # Find a3 using binary search or just a simple loop.
            # val can be up to 2 * 100^3 + 200 = 2,000,200.
            # a3^3 + a3 = val => a3 is around val^(1/3).
            a3_approx = round(val**(1/3))
            for a3 in range(a3_approx - 2, a3_approx + 3):
                if a3 != a1 and a3 != a2 and R(a3) == val:
                    return f"k=2 solution: a1={a1}, a2={a2}, a3={a3}"

    # Check k=3
    for a1 in range(-100, 101):
        for a2 in range(a1 + 1, 101):
            for a3 in range(a2 + 1, 101):
                val = R(a1) + R(a2) + R(a3)
                a4_approx = round(val**(1/3))
                for a4 in range(a4_approx - 2, a4_approx + 3):
                    if a4 != a1 and a4 != a2 and a4 != a3 and R(a4) == val:
                        return f"k=3 solution: a1={a1}, a2={a2}, a3={a3}, a4={a4}"

