def find_counterexample():
    P = lambda x: x**3 + x
    limit = 50
    vals = [P(i) for i in range(-limit, limit + 1)]
    p_set = set(vals)

    # Try c0 values
    for c0 in range(-50, 51):
        # Check k=2: P(a3) = P(a1) + P(a2) + c0
        # Check if there exists any a1, a2 such that P(a1) + P(a2) + c0 is in p_set
        # and a1, a2, a3 are distinct.
        found_k2 = False
        for i in range(-limit, limit + 1):
            for j in range(i + 1, limit + 1):
                val = vals[i + limit] + vals[j + limit] + c0
                if val in p_set:
                    # val = P(a3)
                    # Find a3
                    for k in range(-limit, limit + 1):
                        if k != i and k != j and vals[k + limit] == val:
                            found_k2 = True
                            break
                if found_k2: break
            if found_k2: break

        if found_k2: continue

        # Check k=3: P(a4) = P(a1) + P(a2) + P(a3) + 2*c0
        # We need to know if there exists any a1, a2, a3 such that P(a4) = P(a1) + P(a2) + P(a3) + 2*c0
        found_k3 = False
        for i in range(-limit, limit + 1):
            for j in range(i + 1, limit + 1):
                for l in range(j + 1, limit + 1):
                    val = vals[i + limit] + vals[j + limit] + vals[l + limit] + 2*c0
                    if val in p_set:
                        for m in range(-limit, limit + 1):
                            if m != i and m != j and m != l and vals[m + limit] == val:
                                found_k3 = True
                                break
                    if found_k3: break
                if found_k3: break
            if found_k3: break

        if not found_k3:
            return c0
    return None

