def check_k(R, k, max_val=20):
    # R is a list of coefficients [c0, c1, c2, ..., cd]
    # R(x) = c0 + c1*x + c2*x^2 + ... + cd*x^d
    def f(x):
        res = 0
        for i, c in enumerate(R):
            res += c * (x**i)
        return res

    # We want to find k+1 distinct integers a1, ..., ak+1
    # such that f(ak+1) = sum(f(ai) for i in 1..k)
    # Since f is a polynomial, we can search in a range.
    # This is a very limited search.

    # Let's try to find if any such k+1 distinct integers exist.
    # Because a_i can be negative, we check a range around 0.
    vals = []
    for x in range(-max_val, max_val + 1):
        vals.append((x, f(x)))

    # Try all combinations of k+1 distinct values from vals
    # This is too slow for k=3.
    # Let's try a different approach for k=1, 2, 3.

    # k=1: f(a2) = f(a1)
    if k == 1:
        for i in range(len(vals)):
            for j in range(i + 1, len(vals)):
                if vals[i][1] == vals[j][1]:
                    return True
        return False

    # k=2: f(a3) = f(a1) + f(a2)
    if k == 2:
        # Use a dictionary to store sums of two distinct f(ai)
        # To ensure a1, a2, a3 are distinct, we need to be careful.
        for i in range(len(vals)):
            for j in range(i + 1, len(vals)):
                s = vals[i][1] + vals[j][1]
                # Now check if s = f(a3) for some a3 != a1, a2
                for l in range(len(vals)):
                    if l != i and l != j:
                        if vals[l][1] == s:
                            return True
        return False

    # k=3: f(a4) = f(a1) + f(a2) + f(a3)
    if k == 3:
        # Precompute all sums of 3 distinct f(ai)
        # This is still a bit slow.
        for i in range(len(vals)):
            for j in range(i + 1, len(vals)):
                for l in range(j + 1, len(vals)):
                    s = vals[i][1] + vals[j][1] + vals[l][1]
                    for m in range(len(vals)):
                        if m != i and m != j and m != l:
                            if vals[m][1] == s:
                                return True
        return False

    return False

