    for a1 in range(-M, M+1):
        for a2 in range(a1+1, M+1):
            val = 1 + g(a1) + g(a2)
            # Check if val is real and non-negative before taking cube root
            if val >= 0:
                a3_approx = int(val**(1/3))
                for a3 in range(a3_approx - 2, a3_approx + 3):
                    if a3 >= -M and a3 <= M and a3 != a1 and a3 != a2:
                        if g(a3) == val:
                            found_k2 = True
                            break
            else:
                # If val is negative, a3 is negative.
                # val = a3^3 + 2*a3. Let a3 = -y, y > 0.
                # -y^3 - 2y = val  => y^3 + 2y = -val
                neg_val = -val
                y_approx = int(neg_val**(1/3))
                for y in range(y_approx - 2, y_approx + 3):
                    a3 = -y
                    if a3 >= -M and a3 <= M and a3 != a1 and a3 != a2:
                        if g(a3) == val:
                            found_k2 = True
                            break
            if found_k2: break
