def check_R(coeffs, k_max, n):
    # R(x) = sum(coeffs[i] * x^i)
    # check if there exists k <= k_max and k+1 distinct a_i such that R(ak+1) = sum_{i=1}^k R(ai)

    def R(x):
        res = 0
        for i, c in enumerate(coeffs):
            res += c * (x**i)
        return res

    # This is still hard because a_i can be anything.
    # But let's check a large range.
    limit = 100
    vals = [R(i) for i in range(-limit, limit + 1)]
    # vals[j] corresponds to x = j - limit

    for k in range(1, k_max + 1):
        # Check if there exist k+1 distinct a_i in the range
        # We can use a recursive approach or nested loops for small k
        if k == 1:
            for i in range(len(vals)):
                for j in range(i + 1, len(vals)):
                    if vals[i] == vals[j]:
                        return True, k
        elif k == 2:
            for i in range(len(vals)):
                for j in range(i + 1, len(vals)):
                    target = vals[i] + vals[j]
                    for m in range(len(vals)):
                        if m != i and m != j and vals[m] == target:
                            return True, k
        elif k == 3:
            for i in range(len(vals)):
                for j in range(i + 1, len(vals)):
                    for l in range(j + 1, len(vals)):
                        target = vals[i] + vals[j] + vals[l]
                        for m in range(len(vals)):
                            if m != i and m != j and m != l and vals[m] == target:
                                return True, k
    return False, None

