def check_n_3_thoroughly_v2():
    f = lambda x: x**3 - x**2 + 3*x
    # k=2: f(a1) + f(a2) - 338 = f(a3)
    # Search a1, a2 in a larger range.
    found_k2 = False
    for a1 in range(-200, 201):
        for a2 in range(a1 + 1, 201):
            target = f(a1) + f(a2) - 338
            # We need to check if target = f(a3) for some a3.
            # f(x) is strictly increasing.
            # f(x) = x^3 - x^2 + 3x.
            # x^3 - x^2 + 3x - target = 0.
            # Use the cubic formula or just check integers near the real root.
            # The real root is approximately x = target^(1/3).
            if target == 0:
                a3 = 0
            else:
                # Approximate root
                a3_approx = round(target**(1/3)) if target > 0 else round(-((-target)**(1/3)))
                # Check nearby integers
                for a3 in range(a3_approx - 2, a3_approx + 3):
                    if f(a3) == target:
                        if a3 != a1 and a3 != a2:
                            found_k2 = True
                            break
            if found_k2: break
        if found_k2: break

    # k=3: f(a1) + f(a2) + f(a3) - 676 = f(a4)
    found_k3 = False
    # We need to search a1, a2, a3. This is O(N^3).
    # Let's try a smaller range first.
    for a1 in range(-50, 51):
        for a2 in range(a1 + 1, 51):
            for a3 in range(a2 + 1, 51):
                target = f(a1) + f(a2) + f(a3) - 676
                if target == 0:
                    a4 = 0
                else:
                    a4_approx = round(target**(1/3)) if target > 0 else round(-((-target)**(1/3)))
                    for a4 in range(a4_approx - 2, a4_approx + 3):
                        if f(a4) == target:
                            if a4 != a1 and a4 != a2 and a4 != a3:
                                found_k3 = True
                                break
                if found_k3: break
            if found_k3: break
        if found_k3: break

    return found_k2, found_k3

print(check_n_3_thoroughly_v2())

def get_quotients(k, c_range, limit):
    quotients = set()
    # k=2: (a1^3 + a2^3 - a3^3) / (a3 - a1 - a2)
    if k == 2:
        for a1 in range(-limit, limit):
            for a2 in range(a1 + 1, limit):
                for a3 in range(-limit, limit):
                    if a3 != a1 and a3 != a2:
                        num = a1**3 + a2**3 - a3**3
                        den = a3 - a1 - a2
                        if den != 0 and num % den == 0:
                            c = num // den
                            if c in c_range:
                                quotients.add(c)
    # k=3: (a1^3 + a2^3 + a3^3 - a4^3) / (a4 - a1 - a2 - a3)
    elif k == 3:
        for a1 in range(-limit, limit):
            for a2 in range(a1 + 1, limit):
                for a3 in range(a2 + 1, limit):
                    for a4 in range(-limit, limit):
                        if a4 != a1 and a4 != a2 and a4 != a3:
                            num = a1**3 + a2**3 + a3**3 - a4**3
                            den = a4 - a1 - a2 - a3
                            if den != 0 and num % den == 0:
                                c = num // den
                                if c in c_range:
                                    quotients.add(c)
    return quotients

# We want to find if there is a c such that c is not in quotients for k=2 and k=3.
# However, the problem is for *any* Q, so we need to check *all* c.
# Wait, if for a given c, k=2 or k=3 works, then n=3 is a solution for that c.
# We need to know if there is *any* c such that neither k=2 nor k=3 works.
# If such a c exists, then n=3 is not a solution.

limit = 20
c_range = range(1, 1000)
q2 = get_quotients(2, c_range, limit)
q3 = get_quotients(3, c_range, limit)

all_q = q2.union(q3)
missing = [c for c in c_range if c not in all_q]
print(f"Missing c: {missing[:10]} ... Total missing: {len(missing)}")
